absl::Status ParseTreeSerializer::Serialize(const ASTQuery* node,
                                            ASTQueryProto* proto) {
  GOOGLESQL_RETURN_IF_ERROR(Serialize(node, proto->mutable_parent()));
  if (node->with_clause_ != nullptr) {
    GOOGLESQL_RETURN_IF_ERROR(Serialize(node->with_clause_, proto->mutable_with_clause()));
  }
  if (node->query_expr_ != nullptr) {
    GOOGLESQL_RETURN_IF_ERROR(Serialize(node->query_expr_, proto->mutable_query_expr()));
  }
  if (node->order_by_ != nullptr) {
    GOOGLESQL_RETURN_IF_ERROR(Serialize(node->order_by_, proto->mutable_order_by()));
  }
  if (node->limit_offset_ != nullptr) {
    GOOGLESQL_RETURN_IF_ERROR(Serialize(node->limit_offset_, proto->mutable_limit_offset()));
  }
  proto->set_is_nested(node->is_nested_);
  proto->set_is_pivot_input(node->is_pivot_input_);
  for (int i = 0; i < node->pipe_operator_list().length(); i++) {
    const ASTPipeOperator* pipe_operator_list_ = node->pipe_operator_list().at(i);
    AnyASTPipeOperatorProto* proto2 = proto->add_pipe_operator_list();
    GOOGLESQL_RETURN_IF_ERROR(Serialize(pipe_operator_list_, proto2));
  }
  if (node->lock_mode_ != nullptr) {
    GOOGLESQL_RETURN_IF_ERROR(Serialize(node->lock_mode_, proto->mutable_lock_mode()));
  }
  return absl::OkStatus();
}
absl::Status ParseTreeSerializer::Serialize(const ASTQuery* node,
                                           AnyASTQueryExpressionProto* proto) {
  ASTQueryProto* ast_query_proto =
      proto->mutable_ast_query_node();
  GOOGLESQL_RETURN_IF_ERROR(Serialize(node, ast_query_proto));
  return absl::OkStatus();
}
absl::StatusOr<ASTQuery*> ParseTreeSerializer::Deserialize(
    const ASTQueryProto& proto,
    IdStringPool* id_string_pool,
    googlesql_base::UnsafeArena* arena,
    std::vector<std::unique_ptr<ASTNode>>* allocated_ast_nodes) {
  ASTQuery* node = googlesql_base::NewInArena<ASTQuery>(arena);
  allocated_ast_nodes->push_back(std::unique_ptr<ASTNode>(node));
  GOOGLESQL_RETURN_IF_ERROR(DeserializeAbstract(node,
                                      proto.parent(),
                                      id_string_pool,
                                      arena,
                                      allocated_ast_nodes));
  GOOGLESQL_RETURN_IF_ERROR(DeserializeFields(node,
                                    proto,
                                    id_string_pool,
                                    arena,
                                    allocated_ast_nodes));
  return node;
}
absl::Status ParseTreeSerializer::DeserializeFields(
      ASTQuery* node, const ASTQueryProto& proto,
      IdStringPool* id_string_pool,
      googlesql_base::UnsafeArena* arena,
      std::vector<std::unique_ptr<ASTNode>>* allocated_ast_nodes) {
  if (proto.has_with_clause()) {
    node->AddChild(Deserialize(proto.with_clause(),
                   id_string_pool,
                   arena,
                   allocated_ast_nodes).value());
  }
  if (proto.has_query_expr()) {
    node->AddChild(Deserialize(proto.query_expr(),
                   id_string_pool,
                   arena,
                   allocated_ast_nodes).value());
  }
  if (proto.has_order_by()) {
    node->AddChild(Deserialize(proto.order_by(),
                   id_string_pool,
                   arena,
                   allocated_ast_nodes).value());
  }
  if (proto.has_limit_offset()) {
    node->AddChild(Deserialize(proto.limit_offset(),
                   id_string_pool,
                   arena,
                   allocated_ast_nodes).value());
  }
  if (proto.has_lock_mode()) {
    node->AddChild(Deserialize(proto.lock_mode(),
                   id_string_pool,
                   arena,
                   allocated_ast_nodes).value());
  }
  node->is_nested_ = proto.is_nested();
  node->is_pivot_input_ = proto.is_pivot_input();
  for (int i=0; i < proto.pipe_operator_list_size(); i++) {
    node->AddChild(Deserialize(proto.pipe_operator_list(i),
                               id_string_pool,
                               arena,
                               allocated_ast_nodes).value());
  }
  return absl::OkStatus();
}

