absl::Status ParseTreeSerializer::Serialize(const ASTSelect* node,
                                            ASTSelectProto* proto) {
  GOOGLESQL_RETURN_IF_ERROR(Serialize(node, proto->mutable_parent()));
  if (node->hint_ != nullptr) {
    GOOGLESQL_RETURN_IF_ERROR(Serialize(node->hint_, proto->mutable_hint()));
  }
  if (node->with_modifier_ != nullptr) {
    GOOGLESQL_RETURN_IF_ERROR(Serialize(node->with_modifier_, proto->mutable_with_modifier()));
  }
  proto->set_distinct(node->distinct_);
  if (node->select_as_ != nullptr) {
    GOOGLESQL_RETURN_IF_ERROR(Serialize(node->select_as_, proto->mutable_select_as()));
  }
  if (node->select_list_ != nullptr) {
    GOOGLESQL_RETURN_IF_ERROR(Serialize(node->select_list_, proto->mutable_select_list()));
  }
  if (node->from_clause_ != nullptr) {
    GOOGLESQL_RETURN_IF_ERROR(Serialize(node->from_clause_, proto->mutable_from_clause()));
  }
  if (node->where_clause_ != nullptr) {
    GOOGLESQL_RETURN_IF_ERROR(Serialize(node->where_clause_, proto->mutable_where_clause()));
  }
  if (node->group_by_ != nullptr) {
    GOOGLESQL_RETURN_IF_ERROR(Serialize(node->group_by_, proto->mutable_group_by()));
  }
  if (node->having_ != nullptr) {
    GOOGLESQL_RETURN_IF_ERROR(Serialize(node->having_, proto->mutable_having()));
  }
  if (node->qualify_ != nullptr) {
    GOOGLESQL_RETURN_IF_ERROR(Serialize(node->qualify_, proto->mutable_qualify()));
  }
  if (node->window_clause_ != nullptr) {
    GOOGLESQL_RETURN_IF_ERROR(Serialize(node->window_clause_, proto->mutable_window_clause()));
  }
  return absl::OkStatus();
}
