absl::Status ParseTreeSerializer::Serialize(const ASTCreateIndexStatement* node,
                                            ASTCreateIndexStatementProto* proto) {
  GOOGLESQL_RETURN_IF_ERROR(Serialize(node, proto->mutable_parent()));
  if (node->name_ != nullptr) {
    GOOGLESQL_RETURN_IF_ERROR(Serialize(node->name_, proto->mutable_name()));
  }
  if (node->table_name_ != nullptr) {
    GOOGLESQL_RETURN_IF_ERROR(Serialize(node->table_name_, proto->mutable_table_name()));
  }
  if (node->optional_table_alias_ != nullptr) {
    GOOGLESQL_RETURN_IF_ERROR(Serialize(node->optional_table_alias_, proto->mutable_optional_table_alias()));
  }
  if (node->optional_index_unnest_expression_list_ != nullptr) {
    GOOGLESQL_RETURN_IF_ERROR(Serialize(node->optional_index_unnest_expression_list_, proto->mutable_optional_index_unnest_expression_list()));
  }
  if (node->index_item_list_ != nullptr) {
    GOOGLESQL_RETURN_IF_ERROR(Serialize(node->index_item_list_, proto->mutable_index_item_list()));
  }
  if (node->optional_index_storing_expressions_ != nullptr) {
    GOOGLESQL_RETURN_IF_ERROR(Serialize(node->optional_index_storing_expressions_, proto->mutable_optional_index_storing_expressions()));
  }
  if (node->optional_partition_by_ != nullptr) {
    GOOGLESQL_RETURN_IF_ERROR(Serialize(node->optional_partition_by_, proto->mutable_optional_partition_by()));
  }
  if (node->options_list_ != nullptr) {
    GOOGLESQL_RETURN_IF_ERROR(Serialize(node->options_list_, proto->mutable_options_list()));
  }
  proto->set_is_unique(node->is_unique_);
  proto->set_is_search(node->is_search_);
  if (node->spanner_interleave_clause_ != nullptr) {
    GOOGLESQL_RETURN_IF_ERROR(Serialize(node->spanner_interleave_clause_, proto->mutable_spanner_interleave_clause()));
  }
  proto->set_spanner_is_null_filtered(node->spanner_is_null_filtered_);
  proto->set_is_vector(node->is_vector_);
  return absl::OkStatus();
}
