absl::Status ParseTreeSerializer::Serialize(const ASTGraphPathPattern* node,
                                            ASTGraphPathPatternProto* proto) {
  GOOGLESQL_RETURN_IF_ERROR(Serialize(node, proto->mutable_parent()));
  if (node->hint_ != nullptr) {
    GOOGLESQL_RETURN_IF_ERROR(Serialize(node->hint_, proto->mutable_hint()));
  }
  if (node->where_clause_ != nullptr) {
    GOOGLESQL_RETURN_IF_ERROR(Serialize(node->where_clause_, proto->mutable_where_clause()));
  }
  if (node->path_mode_ != nullptr) {
    GOOGLESQL_RETURN_IF_ERROR(Serialize(node->path_mode_, proto->mutable_path_mode()));
  }
  for (int i = 0; i < node->input_pattern_list().length(); i++) {
    const ASTGraphPathBase* input_pattern_list_ = node->input_pattern_list().at(i);
    AnyASTGraphPathBaseProto* proto2 = proto->add_input_pattern_list();
    GOOGLESQL_RETURN_IF_ERROR(Serialize(input_pattern_list_, proto2));
  }
  proto->set_parenthesized(node->parenthesized_);
  if (node->search_prefix_ != nullptr) {
    GOOGLESQL_RETURN_IF_ERROR(Serialize(node->search_prefix_, proto->mutable_search_prefix()));
  }
  if (node->path_name_ != nullptr) {
    GOOGLESQL_RETURN_IF_ERROR(Serialize(node->path_name_, proto->mutable_path_name()));
  }
  return absl::OkStatus();
}
